// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleSuicide} from "../src/SimpleSuicide.sol";

contract InvMutTest is Test {
    SimpleSuicide c;
    function setUp() public { c = new SimpleSuicide(); }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0);
        // owner of c is this test contract (deployer)
        vm.deal(address(c), amount);
        c.sudicideAnyone();
        assertTrue(address(c).balance == 0, "contract must be empty after selfdestruct");
    }
}
